  "上部の「全画面」またはFキーで図を全画面に。右下の小窓で正面と平面を入れ替えられます": "위쪽의 ‘전체 화면’ 또는 F 키로 도면을 전체 화면으로 봅니다. 오른쪽 아래의 작은 창에서 정면도와 평면도를 바꿀 수 있습니다",
