  "本番の暗さ": "공연 때의 어둠",
  "シーンのキューで点いている灯体の見え方。下の段ほど図が重くなります。「本番の暗さ」は作業灯を消して、光の当たる所だけを見せます": "씬의 큐에서 켜진 조명기구가 어떻게 표시되는지 정합니다. 아래 단계일수록 도면 처리에 더 많은 자원이 듭니다. ‘공연 때의 어둠’은 작업등을 끄고 빛이 닿는 곳만 보여 줍니다",
  "「照明の光だまり」を出しているとき、灯体から落ちる場所まで伸びる光の帯も出す。さらに重くなります": "‘조명 빛 영역’을 표시할 때 조명기구에서 빛이 닿는 곳까지 이어지는 빛의 띠도 표시합니다. 처리 부담이 더 커집니다",
  "照明の光の筋": "조명 빛줄기",
  "「照明の光だまり」を出しているとき、光の当たっていない所を暗くする。正面図・平面図・3Dカメラのすべてに効きます": "‘조명 빛 영역’을 표시할 때 빛이 닿지 않는 곳을 어둡게 합니다. 정면도·평면도·3D 카메라에 모두 적용됩니다",
  "全画面表示で、絵の下にシーン名と説明を出す": "전체 화면에서 도면 아래에 씬 이름과 설명을 표시합니다",
  "シーンのキューで点いている灯体の、光が落ちる場所を正面図・平面図に出す。図が重くなります": "씬의 큐에서 켜진 조명기구의 빛이 닿는 곳을 정면도와 평면도에 표시합니다. 도면 처리 부담이 커집니다",
