  "ショー地図に、転換ごとの移動量・動く人数・出入りの数を出す": "공연 지도에 전환별 이동 거리·이동 인원·출입 횟수를 표시합니다",
  "同時に動く演者の動線がぶつかりそうな所に、平面図で印を出す": "동시에 움직이는 출연자의 이동 경로가 충돌할 수 있는 곳을 평면도에 표시합니다",
  "高所の下の注意": "높은 장비 아래 주의",
  "ポールやトラピーズの真下に人が居るとき、平面図に印を出す": "폴이나 트라페즈 바로 아래에 사람이 있으면 평면도에 표시합니다",
  "引いた絵を軽くする": "멀리 보이는 그림 단순화",
  "アリーナ・ドームなど大きい会場の3Dカメラで、遠くの客席を簡単に描いて動きを軽くする。近くの見え方は変わりません": "아레나·돔 등 큰 공연장의 3D 카메라에서 멀리 있는 객석을 단순하게 그려 동작을 가볍게 합니다. 가까운 곳의 모습은 바뀌지 않습니다",
