  "ばらす": "풀기",
  "組をやめて、一つずつの明かりに戻す": "묶음을 해제하고 개별 조명으로 되돌립니다",
  "SS（袖から横切って）": "사이드 조명(무대 옆에서 가로지르며)",
  "前明かり（客席の上から顔へ）": "전면 조명(객석 위쪽에서 얼굴로)",
  "転がし（床置きから体へ）": "바닥 조명(바닥에서 몸으로)",
  "まだ何も登録していません。名前と種類を選んで追加してください。": "아직 등록된 항목이 없습니다. 이름과 종류를 선택해 추가해 주세요.",
  "この舞台に出る演者、大道具、小道具を、まとめてここに登録します。 寸法や色はここで決め、シーンごとに舞台の上か裏かを切り替えます。明かりは別の項目です。追加したものはそのシーンの舞台に出ます。": "이 무대에 나올 출연자·대도구·소품을 여기에서 함께 등록합니다. 치수와 색을 정하고 씬마다 무대 위 또는 뒤에 둘지 선택합니다. 조명은 별도 항목입니다. 새 항목은 현재 씬의 무대에 배치됩니다.",
  "この舞台に出る演者、大道具、小道具を、まとめてここに登録します。寸法や色はここで決め、シーンごとに舞台の上か裏かを切り替えます。追加したものはそのシーンの舞台に出ます。": "이 무대에 나올 출연자·대도구·소품을 여기에서 함께 등록합니다. 치수와 색을 정하고 씬마다 무대 위 또는 뒤에 둘지 선택합니다. 새 항목은 현재 씬의 무대에 배치됩니다.",
  "8. 舞台機構を設定してください": "8. 무대 기계를 설정해 주세요",
  "7. 壁を設置してください": "7. 벽을 설치해 주세요",
  "四角または丸を選び、右の平面図でドラッグしてください。高さは天井と同じです。通れない場所として扱います。": "사각형 또는 원을 선택한 뒤 오른쪽 평면도에서 드래그해 주세요. 높이는 천장과 같고 통과할 수 없는 공간으로 취급합니다.",
  "いまの舞台装置の並びに名前をつけて残します。別のシーンで呼び出したり、いまの並びへ足したりできます。演者は含みません。": "현재 무대 장치 배치에 이름을 붙여 저장합니다. 다른 씬에서 불러오거나 현재 배치에 추가할 수 있습니다. 출연자는 포함되지 않습니다.",
  "照明は、どこから出てどこへ落ちるかを持ちます。 種類ごとに仕込む場所と当てる高さの既定値が入ります。 「照明を動かす」に切り替えると、灯体の丸い印と、当たる輪をそれぞれ掴んで動かせます。動線を引くと、灯体はそのままで当たる先だけが動きます。": "조명에는 빛이 시작되는 곳과 닿는 곳이 있습니다. 종류별로 설치 위치와 비추는 높이의 기본값이 정해집니다. ‘조명 이동’으로 전환하면 조명기구의 둥근 표시와 빛이 닿는 원을 각각 잡아 옮길 수 있습니다. 이동 경로를 그리면 기구는 그대로 두고 빛이 닿는 곳만 움직입니다.",
  "照明は、どこから出てどこへ落ちるかを持ちます。 種類ごとに仕込む場所と当てる高さの既定値が入ります。 詳細な照明編集は、上部の「照明」で行います。": "조명에는 빛이 시작되는 곳과 닿는 곳이 있습니다. 종류별로 설치 위치와 비추는 높이의 기본값이 정해집니다. 자세한 조명 편집은 위쪽의 ‘조명’에서 진행합니다.",
