  "可": "가능",
  "3番で追加ステージ、5番または6番で客席・舞台袖を描けます。": "3단계에서 추가 무대를, 5단계 또는 6단계에서 객석과 무대 옆 공간을 그릴 수 있습니다.",
  "配置モードを選択してください": "배치 모드를 선택해 주세요",
  "5番または6番を選択してください": "5단계 또는 6단계를 선택해 주세요",
  "4番または5番を選んで、右の平面図で四角を描いてください。": "4단계 또는 5단계를 선택한 뒤 오른쪽 평면도에 사각형을 그려 주세요.",
  "選択モードです。辺をタップすると客席範囲を追加できます。": "선택 모드입니다. 변을 탭하면 객석 범위를 추가할 수 있습니다.",
  "客席範囲を選択していません。舞台の辺をタップして範囲を追加・解除できます。": "객석 범위가 선택되지 않았습니다. 무대의 변을 탭해 범위를 추가하거나 해제할 수 있습니다.",
  "選択モードです。辺をタップすると壁沿いに立ち見の観客を置けます。": "선택 모드입니다. 변을 탭하면 벽을 따라 서서 보는 관객을 배치할 수 있습니다.",
  "観客の帯はまだありません": "아직 관객 구역 띠가 없습니다",
  "座り（OFFは立ち見）": "앉아서 보기(끄면 입석)",
  "全周に配置": "전체 둘레에 배치",
