  "シーンごとに回転角・高さ・開きなどを変えられる舞台機構です。動きの再生や安全計算は行いません。": "씬마다 회전 각도·높이·열림 정도 등을 바꿀 수 있는 무대 기계입니다. 움직임을 재생하거나 안전 계산을 하지는 않습니다.",
  "盆・回り舞台": "회전무대",
