  "振り落とし・上下する幕": "떨어뜨리거나 위아래로 움직이는 막",
  "ホリゾント幕": "하늘막",
  "水面・可動プール床": "수면 · 이동식 수영장 바닥",
  "既製プリセット": "기본 제공 프리셋",
  "寸法は推定値です。配置後に一つずつ動かし、寸法を直せます。": "치수는 추정값입니다. 배치한 뒤 하나씩 옮기고 치수를 수정할 수 있습니다.",
  "回転角": "회전 각도",
  "回転速度": "회전 속도",
  "シーンの間じゅう盆が回り続ける速さ。0で止まる。回転角は開始位相になる": "씬이 진행되는 동안 회전무대가 계속 도는 속도입니다. 0이면 멈춥니다. 회전 각도는 시작 위치가 됩니다",
  "傾斜角": "경사 각도",
